import icontract
from typing import List


@icontract.ensure(lambda a, b, result: all((x in a) != (x in b) for x in result))
@icontract.ensure(lambda result: all(result[i] <= result[i + 1] for i in range(len(result) - 1)))
@icontract.ensure(lambda a, b, result: all((x not in result) if x in b else (x in result) for x in a))
@icontract.ensure(lambda a, b, result: all((x not in result) if x in a else (x in result) for x in b))
def dissimilarElements(a: List[int], b: List[int]) -> List[int]:
    values = set()
    for x in a:
        if x not in b:
            values.add(x)
    for x in b:
        if x not in a:
            values.add(x)
    return sorted(values)
